DO $orphan$
DECLARE
  candidate_ids uuid[] := ARRAY[
    '01a18451-bf7b-73bf-873f-7c73da1a8240'::uuid,
    '01a18452-716b-7202-a319-397964ed6cab'::uuid
  ];
BEGIN
  PERFORM set_config('lock_timeout', '10s', true);
  LOCK TABLE "dentistry"."Appointment", "dentistry"."AppointmentService", "dentistry"."ClinicalEncounter", "dentistry"."ClinicalFile", "dentistry"."Payment" IN ACCESS EXCLUSIVE MODE;

  IF EXISTS (
    SELECT 1 FROM "dentistry"."Appointment"
    WHERE "id" = ANY(candidate_ids) AND "status" <> 'SCHEDULED'
  ) THEN
    RAISE EXCEPTION 'Reviewed orphan appointment status changed; stop and review data';
  END IF;

  IF EXISTS (SELECT 1 FROM "dentistry"."AppointmentService" WHERE "appointmentId" = ANY(candidate_ids))
     OR EXISTS (SELECT 1 FROM "dentistry"."ClinicalEncounter" WHERE "appointmentId" = ANY(candidate_ids))
     OR EXISTS (SELECT 1 FROM "dentistry"."ClinicalFile" WHERE "appointmentId" = ANY(candidate_ids))
     OR EXISTS (SELECT 1 FROM "dentistry"."Payment" WHERE "appointmentId" = ANY(candidate_ids)) THEN
    RAISE EXCEPTION 'Reviewed orphan appointment acquired dependent records; stop and review data';
  END IF;

  DELETE FROM "dentistry"."Appointment"
  WHERE "id" = ANY(candidate_ids) AND "patientId" IS NULL AND "status" = 'SCHEDULED';

  IF EXISTS (SELECT 1 FROM "dentistry"."Appointment" WHERE "patientId" IS NULL) THEN
    RAISE EXCEPTION 'Other appointment rows have no patient; reconcile them before migration';
  END IF;

  ALTER TABLE "dentistry"."Appointment" ALTER COLUMN "patientId" SET NOT NULL;
END;
$orphan$;
